/* ==UserStyle==
@name							S1 NUX
@namespace				userstyles.world
@author						pgain2004 <pgain2004@gmail.com>
@description			相对熟悉CSS后新写的，窄屏自适应，适配度高。依赖一些CSS3特性和emoji库，较老系统(如Win7)显示效果可能打折扣。tag:S1 stage1st stage1 saraba1st 泥潭 婆罗门论坛
@version					2026.1.29
@supportURL				https://stage1st.com/2b/thread-1826103-1-1.html
@license					CC-BY-NC-SA-4.0
@preprocessor			less

@var checkbox autotheme "自适应色调主题" 1

@var select lighttheme "浅色调/默认主题" {
"Tea:[亮]红茶*": "tea",
"Tea_alt:[亮]红茶Alt": "tea_alt",
"Beach:[亮]青滩": "beach",
"Shit:[亮]屎黄": "shit",
"Dark:[暗]暗夜": "dark",
"MuxDark:[暗]MUX暗": "muxdark",
"Blueprint:[暗]蓝图": "blueprint",
"Vine:[暗]酒红": "vine",
"Jungle:[暗]密林": "jungle",
"Custom:自定义": "custom"
}

@var select darktheme "深色调主题" {
"Tea:[亮]红茶*": "tea",
"Tea_alt:[亮]红茶Alt": "tea_alt",
"Beach:[亮]青滩": "beach",
"Shit:[亮]屎黄": "shit",
"Dark:[暗]暗夜": "dark",
"MuxDark:[暗]MUX暗": "muxdark",
"Blueprint:[暗]蓝图": "blueprint",
"Vine:[暗]酒红": "vine",
"Jungle:[暗]密林": "jungle",
"Custom:自定义": "custom"
}

@var select topicfont "默认字体" {
	"0:维持原样*":"initial",
	"1:微软雅黑": "'微软雅黑',sans-serif",
	"2:思源黑体": "'思源黑体 CN',sans-serif",
	"3:思源宋体": "'思源宋体 CN',serif",
	"4:苹方": "'苹方',sans-serif",
	"5:新宋体": "'新宋体',serif",
	"6:自定义": "@customfont"
}

@var text customfont "字体自定义(先从前面选自定义)" "Microsoft Yahei"

@var checkbox signature_autohide "签名自动隐藏" 1

@var select userinfo "主题内用户信息" {
	"userinfo_auto1:鼠标悬浮显示(风格1)*":"autohide1",
	"userinfo_auto2:鼠标悬浮显示(风格2)":"autohide2",
	"userinfo_always:总是显示": "alwaysshow"
}

@var checkbox fav "主页-收藏板块" 1
@var checkbox hot "主页-热门新区" 1
@var checkbox main "主页-主板块" 1
@var checkbox webgame "主页-网游板块" 1
@var checkbox support "主页-内野" 1
@var checkbox link "主页-友情链接" 1
@var checkbox online "主页-在线会员列表" 1
@var checkbox forcenarrow "强制宽度" 0
@var checkbox forcenarrownav "强制顶栏宽度" 0
@var number custom_width "自定义宽度(px)" [960,0,12000,1,'px']
@var checkbox thin_autoexpand "窄屏下页码栏悬浮展开" 0
@var checkbox hide_narrow_name "窄屏列表隐藏发帖者与时间" 0
@var checkbox qmenuonright "快捷导航右置" 0
@var checkbox bigindex "加大首页" 0
@var checkbox rules "版头悬浮收展" 1
@var checkbox fontreverse "字体反色匹配(部分)" 1
@var checkbox thinscroll "窄滚动条" 1
@var text postimage_maxheight "帖内图片最大高度(需要填单位)" "none"
@var text postimage_maxwidth "帖内图片最大宽度(需要填单位)" "100%"

@var text customtheme_light "自定主题[亮](不换行,首尾加英文单引号)" "'--bg:#ecedeb;--pri:#d1d9c1;--prid:#cc9;--pril:#e5e9df;--bn:#0b7ac9;--bnd:#0555ba;--sec:#0095ff;--secp:#00acff;--t:#022C80;--tl:#3159a9;--tg:#889dc8;--pt:#022C80;--ptl:#3159a9;--icl:#fff;--ic:#ccc;--icd:#999;--icdd:#555;--icddd:#000;--shd:#555;--shdl:#999;'"

@var text customtheme_dark "自定主题[暗](不换行,首尾加英文单引号)" "'--bg:#161616;--pri:#263034;--prid:#344042;--pril:#1b2326;--bn:#072;--bnd:#051;--sec:#7b0;--secp:#7c3;--t:#a2aaaf;--tl:#c7d0d6;--tg:#566266;--pt:#a2aaaf;--ptl:#c7d0d6;--icl:#000;--ic:#333;--icd:#666;--icdd:#ccc;--icddd:#fff;--shd:#000;--shdl:#161616;'"

==/UserStyle== */
@-moz-document domain("saraba1st.com"), domain("stage1st.com") { /*1 通用*/
	/*1-0 配色*/
	/*
bg(background)：背景色；
pri(primary)：主色调，主要作为顶栏和标题栏背景；
prid(primary-dark)：深主色调(暗色主题：浅)，主要用来为模块勾边；
pril(primary-light)：浅主色调(暗色：深)；
bn(button)：按钮色；
bnd(button-dark)：深按钮色；
sec(secondary)：副色调；
secp(secondary-in-primary)：主色调背景下的副色调；
t(text)：默认文本色；
tl(text-light)：浅文本色；
tg(text-grey)：灰文本色；
pt(primarytext)：主色调背景下文本色；
ptl(primarytext-light)：主色调背景下浅文本色；
ic(icon)：图标色；
icl(icon-light)：浅图标色；
icd(icon-dark)：深图标色；
icdd(icon-darker)：更深图标色；
icddd(icon-darkest)：最深图标色；
shd(shadow)：阴影色；
shdl(shadow-light)：浅阴影色；
*/
	.theme_tea() { --darktheme: 0; --bg: #ecedeb; --pri: #d1d9c1; --prid: #cc9; --pril: #e5e9df; --bn: #0b7ac9; --bnd: #0555ba; --sec: #0095ff; --secp: #00acff; --t: #022C80; --tl: #3159a9; --tg: #314672; --tp: #889dc8; --pt: #063288; --ptl: #1041a3; --icl: #fff; --ic: #ccc; --icd: #999; --icdd: #555; --icddd: #000; --shd: #555; --shdl: #999; }
	.theme_tea_alt() { --darktheme: 0; --bg: #f6f7eb; --pri: #d0d7bb; --prid: #CCCC99; --pril: #d7dec7; --bn: #689d6a; --bnd: #427b58; --sec: #d65d0e; --secp: #af3a03; --t: #504945; --tl: #665c54; --tg: #928374; --pt: #076678; --ptl: #458588; --ic: #ccc; --icl: #fff; --icd: #999; --icdd: #555; --icddd: #000; --shd: #555; --shdl: #999; }
	.theme_beach() { --darktheme: 0; --bg: #e1f0ed; --pri: #43c3ca; --prid: #17b3b2; --pril: #96dedf; --bn: #e67c1a; --bnd: #db6c04; --sec: #e37a17; --secp: #ffcc9c; --t: #192419; --tl: #354735; --pt: #242e24; --ptl: #3a4d3a; --tg: #2f3a2f; --ic: #ccc; --icl: #fff; --icd: #999; --icdd: #555; --icddd: #000; --shd: #103e39; --shdl: #39605c; }
	.theme_shit() { --darktheme: 0; --bg: #e6e8c2; --pri: #827c54; --prid: #706c41; --pril: #cacc9b; --bn: #728e47; --bnd: #516212; --sec: #3faa0a; --secp: #6ece3e; --t: #373322; --tl: #6f6137; --pt: #0a2b14; --ptl: #144718; --tg: #8a825f; --icl: #fff; --ic: #ccc; --icd: #999; --icdd: #555; --icddd: #000; --shd: #48412e; --shdl: #756750; }
	.theme_dark() { --darktheme: 1; --bg: #161616; --pri: #263034; --prid: #344042; --pril: #1b2326; --bn: #072; --bnd: #051; --sec: #7b0; --secp: #7c3; --t: #a2aaaf; --tl: #c7d0d6; --tg: #566266; --pt: #a2aaaf; --ptl: #c7d0d6; --ic: #333; --icl: #000; --icd: #666; --icdd: #ccc; --icddd: #fff; --shd: #000; --shdl: #161616; }
	.theme_muxdark() { --darktheme: 1; --bg: #262626; --pri: #263238; --prid: #2c3f44; --pril: #1f2426; --bn: #30383e; --bnd: #2c3135; --sec: #F26C4F; --secp: #F27C5F; --t: #b4b5af; --tl: #cfd0cb; --tg: #7a7b74; --pt: #b6b9b1; --ptl: #cfd6c7; --icl: #000; --ic: #333; --icd: #666; --icdd: #ccc; --icddd: #fff; --shd: #000; --shdl: #161616; }
	.theme_blueprint() { --darktheme: 1; --bg: #19212f; --pri: #303c55; --prid: #394159; --pril: #232c3c; --bn: #d09300; --bnd: #a45002; --sec: #ffb608; --secp: #ffb608; --t: #cccac3; --tl: #ece9e0; --tg: #949ea6; --pt: #cccac3; --ptl: #ece9e0; --icl: #000; --ic: #333; --icd: #666; --icdd: #ccc; --icddd: #fff; --shd: #12141c; --shdl: #333e62; }
	.theme_vine() { --darktheme: 1; --bg: #413439; --pri: #953a55; --prid: #b54467; --pril: #622638; --bn: #308d46; --bnd: #3f5561; --sec: #36ff72; --secp: #7bffb2; --t: #ffe6f5; --tl: #ece0e5; --tg: #a6949d; --pt: #ffe6f5; --ptl: #ece0e5; --icl: #000; --ic: #333; --icd: #666; --icdd: #ccc; --icddd: #fff; --shd: #1c1217; --shdl: #623351; }
	.theme_jungle() { --darktheme: 1; --bg: #202221; --pri: #26342a; --prid: #445948; --pril: #1e261f; --bn: #5f8e00; --bnd: #1f5500; --sec: #c7e80b; --secp: #c9d586; --t: #a2afa7; --tl: #c7d6ca; --tg: #5e645f; --pt: #aaafa2; --ptl: #cfd6c7; --icl: #000; --ic: #333; --icd: #666; --icdd: #ccc; --icddd: #fff; --shd: #000; --shdl: #161616; }
	.trans_color() { --bgb: hsl(from var(--bg) h s l / 70%); --prib: hsl(from var(--pri) h s l / 70%); --pridb: hsl(from var(--prid) h s l / 70%); --prilb: hsl(from var(--pril) h s l / 70%); --bnb: hsl(from var(--bn) h s l / 70%); --bndb: hsl(from var(--bnd) h s l / 70%); --secb: hsl(from var(--sec) h s l / 70%); --secpb: hsl(from var(--secp) h s l / 70%); }
	:root when (@autotheme = 0) { & when (@lighttheme = tea) { .theme_tea(); }
		& when (@lighttheme = tea_alt) { .theme_tea_alt(); }
		& when (@lighttheme = beach) { .theme_beach(); }
		& when (@lighttheme = shit) { .theme_shit(); }
		& when (@lighttheme = dark) { .theme_dark(); }
		& when (@lighttheme = muxdark) { .theme_muxdark(); }
		& when (@lighttheme = blueprint) { .theme_blueprint(); }
		& when (@lighttheme = vine) { .theme_vine(); }
		& when (@lighttheme = jungle) { .theme_jungle(); }
		& when (@lighttheme = custom) { e(@customtheme_light); }
		.trans_color(); }
	@media (prefers-color-scheme:light) { :root when (@autotheme = 1) { & when (@lighttheme = tea) { .theme_tea(); }
			& when (@lighttheme = tea_alt) { .theme_tea_alt(); }
			& when (@lighttheme = beach) { .theme_beach(); }
			& when (@lighttheme = shit) { .theme_shit(); }
			& when (@lighttheme = dark) { .theme_dark(); }
			& when (@lighttheme = muxdark) { .theme_muxdark(); }
			& when (@lighttheme = blueprint) { .theme_blueprint(); }
			& when (@lighttheme = vine) { .theme_vine(); }
			& when (@lighttheme = jungle) { .theme_jungle(); }
			& when (@lighttheme = custom) { e(@customtheme_light); }
			.trans_color(); } }
	@media (prefers-color-scheme:dark) { :root when (@autotheme = 1) { & when (@darktheme = tea) { .theme_tea(); }
			& when (@darktheme = tea_alt) { .theme_tea_alt(); }
			& when (@darktheme = beach) { .theme_beach(); }
			& when (@darktheme = shit) { .theme_shit(); }
			& when (@darktheme = dark) { .theme_dark(); }
			& when (@darktheme = muxdark) { .theme_muxdark(); }
			& when (@darktheme = blueprint) { .theme_blueprint(); }
			& when (@darktheme = vine) { .theme_vine(); }
			& when (@darktheme = jungle) { .theme_jungle(); }
			& when (@darktheme = custom) { e(@customtheme_dark); }
			.trans_color(); } }
	@bg: var(--bg); @bgb: var(--bgb); @pri: var(--pri); @prib: var(--prib); @prid: var(--prid); @pridb: var(--pridb); @pril: var(--pril); @prilb: var(--prilb); @bn: var(--bn); @bnb: var(--bnb); @bnd: var(--bnd); @bndb: var(--bndb); @sec: var(--sec); @secb: var(--secb); @secp: var(--secp); @secpb: var(--secpb); @t: var(--t); @tl: var(--tl); @tg: var(--tg); @pt: var(--pt); @ptl: var(--ptl); @icl: var(--icl); @ic: var(--ic); @icd: var(--icd); @icdd: var(--icdd); @icddd: var(--icddd); @shd: var(--shd); @shdl: var(--shdl); /*1-1 渐变*/
	*:not(.v-binder-follower-content), *::before, *::after { transition-timing-function: ease; transition-duration: .15s; transition-property: border, border-color, border-radius, background-color, color, box-shadow, font-size, font-weight, text-shadow, opacity, height, line-height, width, max-height, max-width, transform, padding, margin, text-align, text-decoration }
	/*1-2 去除元素*/
	ins.adsbygoogle, #toptb, #nv_forum > .wp.a_h, .hdc.cl h2 a[title = "Stage1st"], #mu, #um .pipe, /*用户信息栏“我的”，因和快捷导航内入口重复*/
	#um #myitem, /*底部导航按钮栏*/
	.pg_viewthread .pgs, .pg_guide .pgs, .pg_forumdisplay .pgs:not(#pgt) > *:not(#fd_page_bottom), .pg_forumdisplay .pgs #fd_page_bottom .pg > *:not(.nxt), /*多余搜索栏部件*/
	.scbar_icon_td, .scbar_hot_td, .boardnav .drag + .bm.bmw, #um > p:nth-child(3), /*广告*/
	.ad, #copy_url, /*帖内悬浮用户卡片*/
	#postlist .card_gender_0, #postlist .card_gender_1, #postlist .card_gender_2, /*板块入口图标*/
	.fl_icn_g, .fl_icn, div[id ^= "category_"] .fl_tb p, div[id ^= "category_"] .fl_i, div[id ^= "category_"] .fl_by, #chart .z, /*地址栏“论坛”入口段*/
	#pt a[href = "forum.php"], #pt a[href = "forum.php"] + em, #pt a[href ^= "forum.php?gid="], #pt a[href ^= "forum.php?gid="] + em, /*[宽屏]去帖内多余用户信息*/
	#postlist .pls dt, #postlist .pls dd:first-of-type, #postlist .pls > p:not(:first-of-type):not(.xg1), #postlist .pls .avatar + img, /*帖内打印和主题切换按钮*/
	.vwthd div.y, .boardnav .bm_h .o, .mn > .fl.bm > .bm.bmw.cl > .bm_h.cl .o, #online .bm_h .o img, #threadlisttableid #separatorline, #threadlisttableid > tbody:not([id ^= "normal"]):not([id ^= "stick"]), /*快速回复左栏*/
	#f_pst .pls, #f_pst .cl::after, .y[href ^= "home.php?mod=spacecp&ac=credit&op=rule"], .mn > .wp.mtn, /*引用框后单换行*/
	.pl .quote + br, /*导航页版头*/
	.pg_guide .boardnav .bm.bml.pbn, /*用户回复列表多余尾格*/
	.pg_guide #threadlist .bw0_all + tbody, a[title = "发起QQ聊天"], .tbn .mt, /*多余定位*/
	.ct2_a::after, .ct2_a .mn .bw0 .tb::after, #selectorBox::after, /*板块页宽翻页按钮*/
	.boardnav #autopbn, /*用户信息页引用符*/
	#delform .xg1 img, #newspecial_menu li:not(.trade):first-child, /*这啥？*/
	iframe#aswift_1, iframe#aswift_2, /*列表头的icn*/
	.tl .th .icn, .pdbt, /*主楼评分收藏原图标*/
	#p_btn i img, .colorbox input + br, img[src *= "//static.saraba1st.com/image/common/online_member.gif"], /*毫无用处的零指向快速搜索入口*/
	#quick_sch, #scform > tbody > tr h1, .td_srchbtn, /*出售信息收纳图标*/
	.trdb .y a img, /*搜索主页原LOGO图*/
	.searchform a[title = "Stage1st"] img, /*帖内投票栏提交按钮前空白*/
	.pcht .selector, .card .pbn.cl::after, .pop_moremenu .pipe, .wp.a_f, /*收藏页原图片*/
	/*用户卡片*/
	#favorite_ul span img, img[alt ^= "刷新"], img[alt = "手机发帖"], .authi > img, .tip_horn, .pg_space .nts .m { display: none!important }
	/*1-3 主布局*/
	.mn { display: flex; flex-direction: column }
	a { text-decoration: none!important }
	/*1-3-1 顶栏*/
	#hd .wp { display: flex; position: fixed; top: 0; width: 100%; height: 36px; background: @prib; padding: 0; z-index: 200; backdrop-filter: blur(24px) }
	/*1-3-1-1 快速导航*/
	#nv { display: flex; width: auto!important; height: auto!important; position: static!important; opacity: 1!important; border: 0; background: 0; flex-grow: 1 }
	#nv_ph { flex-grow: 0 }
	#qmenu { order: 0; background: 0; height: auto; width: auto; line-height: 36px; margin: 0; padding: 0 8px 0 12px; font-size: 15px; white-space: nowrap; flex-shrink: 0 }
	#qmenu:hover { color: @tl }
	#qmenu_menu { position: fixed!important; left: 0!important; top: 37px!important; border-color: @pri; box-shadow: none; width: auto; height: calc(100%)!important; padding: 0 }
	#qmenu_menu ul.nav a { border-radius: 0; margin: 0; padding: 36px 0 0; background-size: 46%; background-position-y: 8px }
	#qmenu_menu ul.nav a:hover { background-color: @pri }
	#fjump_menu { max-height: 100% }
	#hd .wp > .h_pop { position: fixed!important; top: 36px!important }
	.btda { border: 0 }
	.jump_bdl { display: flex }
	.jump_bdl .bbda { background: @pri; border: 0 }
	.jump_bdl li { background: @bg; border-color: @prid; padding: 0; width: auto; min-width: 150px; height: calc(100vh - 146px) }
	.jump_bdl p { padding: 0 12px }
	.jump_bdl p:hover { background: @pri }
	.jump_bdl p a { padding: 0 }
	.jump_bdl .a a, .jump_bdl .a a:hover, .jump_bdl p a:hover { background: 0 }
	#nv ul { display: flex; flex-grow: 0; justify-content: flex-start }
	#nv li { background: none; height: auto; line-height: 35px }
	#nv li a { color: @t; background: none!important; text-decoration: none; padding: 0 8px; width: calc(100% - 16px); height: 32px; text-align: center; white-space: nowrap }
	#nv li.a { background-color: @pri }
	/*1-3-1-2 搜索栏*/
	#scbar { order: 0; height: auto; border: 0; line-height: normal; margin: 0; padding: 2px 4px; flex-grow: 1; flex-shrink: 0 }
	#scbar_form > table > tbody > tr { display: flex; border: 1px solid @ic; background-color: @bgb; margin: 2px 8px; height: 26px }
	/*1-3-1-2-1 搜索类型*/
	.scbar_type_td { order: 0; background: none; width: 48px }
	#scbar_type { line-height: 26px; padding-left: 12px; height: auto; border: 0; background: 0 }
	#scbar_type_menu { margin-top: -2px; margin-left: 1px; padding: 0; width: 48px; min-width: 0; top: 33px!important; border-color: @ic; border-top: 0; box-shadow: none }
	#scbar_type_menu li { width: 48px }
	#scbar_type_menu li a { padding: 2px 0 2px 10px }
	/*1-3-1-2-2 搜索文本*/
	.scbar_txt_td { order: 1; background: 0 }
	#scbar_txt { padding: 0; background: 0; width: auto; max-width: 120px; height: 100%; border: none; text-indent: 4px }
	/*1-3-1-2-3 搜索按钮*/
	.scbar_btn_td { order: 2; background: 0; width: auto }
	#scbar_btn { height: 27px; width: 32px; padding: 0; margin: 0; background: 0; box-shadow: none; border-radius: 0 }
	#scbar_btn strong { display: none }
	#scbar_btn::before { display: inline-block; content: ''; background: none; position: relative; bottom: 2px; left: 2px; width: 10px; height: 10px; border: 2px solid @t; border-radius: 15px; transform: rotate(140deg); transition: all .15s linear }
	#scbar_btn:hover::before { border-color: @sec }
	#scbar_btn::after { display: inline-block; content: ''; position: relative; right: 1px; bottom: 1px; width: 6px; height: 2.5px; background: @t; border-radius: 2px 0 0 2px; transform: rotate(225deg); transition: all .15s linear }
	#scbar_btn:hover::after { background: @sec }
	/*1-3-1-4 临时搜索栏*/
	#hd h2, .gsib_a, table.gsc-search-box td.gsc-input { padding: 0 }
	form.gsc-search-box { margin: 0 }
	table.gsc-search-box { margin: 0 }
	#gsc-iw-id1 { border-color: @ic }
	input#gsc-i-id1.gsc-input { background: @bgb !important; padding: 0 0 0 6px !important }
	#custom-gcse-search-box { width: auto !important; min-width: 180px }
	.gscb_a { line-height: 24px; vertical-align: middle }
	.gsc-input-box { background: 0 }
	.gsc-modal-background-image-visible { height: 100vh; background: @bgb; opacity: 1; backdrop-filter: blur(24px) }
