	/*13 反色涂黑识别*/
	#postlist font when (@fontreverse = 1) { /* 		color: contrast(@bg, @bg, @pri, 100%); */
		&[color = "black"], &[color = "#000000"], &[color = "#000"], &[style = "color:rgb(0, 0, 0)"] { color: @icddd!important }
