		&[color = "white"], &[color = "#ffffff"], &[color = "#fff"], &[style = "color:rgb(244, 244, 244)"], &[style = "color:rgb(255, 255, 255)"], &[color = "#fffacd"], &[color = "lemonchiffon"] { color: @bg!important }
		&[style = "background-color:white"], &[style = "background-color:#ffffff"], &[style = "background-color:#fff"], &[style = "background-color:rgb(244, 244, 244)"], &[style = "background-color:rgb(255, 255, 255)"], &[style = "background-color:rgb(246, 247, 235)"], &[style = "background-color:#fffacd"], &[style = "background-color:lemonchiffon"] { background-color: transparent!important }
		&[color = "yellow"], &[color = "#ffff00"] { color: @icl!important }
		&[style = "background-color:yellow"], &[style = "background-color:#ffff00"] { background-color: @icl!important }
		&[color = "#191919"], &[color = "#222222"], &[color = "#222"], &[color = "#333333"], &[color = "#333"], &[style = "color:rgb(43, 43, 43)"], &[style = "color:rgb(51, 51, 51)"], &[style = "color:rgb(64, 64, 64)"], &[style = "color:rgb(68, 68, 68)"], &[style = "color:rgb(85, 85, 85)"] { color: @t!important }
		&[style = "background-color:#191919"], &[style = "background-color:#222222"], &[style = "background-color:#222"], &[style = "background-color:#333333"], &[style = "background-color:#333"], &[style = "background-color:rgb(43, 43, 43)"], &[style = "background-color:rgb(51, 51, 51)"], &[style = "background-color:rgb(64, 64, 64)"], &[style = "background-color:rgb(85, 85, 85)"] { background-color: @t!important } }
	/*14 滚动条*/
	/*14-1 滚动条颜色跟随*/
	html::-webkit-scrollbar-track-piece, html::-webkit-scrollbar-track, textarea::-webkit-scrollbar-track-piece, textarea::-webkit-scrollbar-track { background-color: @bg }
	html::-webkit-scrollbar-thumb:vertical, html::-webkit-scrollbar-thumb, textarea::-webkit-scrollbar-thumb:vertical, textarea::-webkit-scrollbar-thumb { background-color: @prid }
	html, textarea, input { scrollbar-color: @prid @bg }
	/*14-2 窄滚动条*/
	html, textarea, input { & when (@thinscroll = 1) { scrollbar-color: @prid @bg; scrollbar-width: thin } } }

