@-moz-document domain("tieba.baidu.com"), domain("www.tieba.com") {
	/* 全局 */

	:root {
		/*
			您可以修改以下变量的值以达到你想要的效果
			-格式为：
				变量名 : 值 ;

			建议您创建新样式，并在当中重新声明相关变量，以创建自己的风格
			同名变量，后声明的有效，请确认你的样式加载顺序
			可参考此示例样式：https://github.com/imaverickk/Tieba-Maverick-UserCSS/tree/main/custom-styles

			如果你使用Stylus，可启用左侧的【实时预览】，便于调整变量时预览效果
		*/

		--m-ecolor: /*[[ecolor]]*/ ;
		/*辅色*/

		--m-ehcolor: /*[[ehcolor]]*/ ;
		/*辅色-高亮*/

		/*提示：辅色请使用与纯白色形成高对比度的颜色*/


		--m-font: /*[[font]]*/ ;
		/*字体*/

		--m-href-color: /*[[hrefcolor]]*/ ;
		/*超链接颜色*/

		--m-href-visited: /*[[visitedcolor]]*/ ;
		/*访问过的超链接颜色*/


		--m-radius: /*[[radius]]*/ ;
		/*主体框架圆角半径*/

		--m-mainwidth: /*[[mainwidth]]*/ ;
		/*主体框架宽度*/

		--m-content-bg: rgba(253,253,253,1) ;
		/*主体框架背景色（https://developer.mozilla.org/zh-CN/docs/Web/CSS/color）*/

		--m-content-shadow: 0 0 20px 2px rgba(0,0,0,.1) ;
		/*主体框架阴影（当主体框架背景色不透明度低于1时，请将此项改为none获得最佳效果；见https://developer.mozilla.org/zh-CN/docs/Web/CSS/box-shadow）*/


		--m-block-darken-lightness: 0%;
		/*分割线亮度（实际影响分割线的灰度，0%为黑色，100%为白色）*/

		--m-line-darken-lightness: 0%;
		/*区块背景亮度（实际影响区块背景的灰度，接受值同上）*/

		--m-line-darken: 1;
		/*分割线深化倍率（调整页面各处分割线的不透明度倍率，0.5表示分割线深度减半，0则去除分割线，依此类推）*/

		--m-block-darken: 1;
		/*区块背景深化倍率（调整页面各处区块背景的不透明度倍率，接受值同上）*/


		--m-light-min: 0% ;
		/*最低亮度（字体&控件的最低亮度）*/

