	/*贴吧时光轴（剑灵吧）*/
	.star_collect_time_axis_body{
		background: var(--m-block-d004);
		border: none !important;
		border-top: 1px solid var(--m-line-d004) !important;
	}
	.star_time_axis .time_axis_summary{
		background: var(--m-block-b002);
	}
