		border-color: var(--m-line-b004);
	}
	.star_time_axis .time_axis_item_hover .time_axis_summary{
		border-color: var(--m-line-b010);
	}
	.star_time_axis h6 a{
		color: var(--m-light-40);
	}
	.star_collect_time_axis_body .time_axis_source{
		color: var(--m-light-70);
	}
	.star_collect_time_axis_body .time_axis_time{
		background: none;
		color: var(--m-light-50);
	}
	.star_time_axis_prev,
	.star_time_axis_next{
		background: none;
		display: flex;
