		justify-content: center;
		color: var(--m-light-60);
	}
	.star_time_axis_prev:before,
	.star_time_axis_next:before{
		font-family: 'Material Icons';
	}
	.star_time_axis_prev:before{
		content: "\e5e0";
	}
	.star_time_axis_next:before{
		content: "\e5e1";
	}
	.star_collect_time_axis_body .star_time_axis_prev_hover,
	.star_collect_time_axis_body .star_time_axis_next_hover{
		color: var(--m-light-50);
	}
	.star_collect_time_axis_body .prev_disabled,
	.star_collect_time_axis_body .next_disabled{
		opacity: 0;
	}
	.star_collect_time_axis_body .star_time_axis_arrow{
		display: none;
	}
	.platform_star_time_axis_arrow_container{
		background: none !important;
		background-color: var(--m-white-color) !important;
		border-radius: 50%;
